def stable_unique(items):
    def deep_equal(a, b):
        if type(a) != type(b):
            return False
        if isinstance(a, dict):
            if len(a) != len(b):
                return False
            for k, v in a.items():
                if k not in b:
                    return False
                if not deep_equal(v, b[k]):
                    return False
            return True
        if isinstance(a, list):
            if len(a) != len(b):
                return False
            for x, y in zip(a, b):
                if not deep_equal(x, y):
                    return False
            return True
        return a == b

    result = []
    for item in items:
        if not any(deep_equal(item, existing) for existing in result):
            result.append(item)
    return result
