def merge_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("Input must be a list of tuples.")

    # Validate and copy intervals to avoid modifying the caller's list
    copied = []
    for interval in intervals:
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise ValueError("Each interval must be a tuple of two integers.")
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Interval bounds must be integers.")
        if start > end:
            raise ValueError("Interval start must be less than or equal to end.")
        copied.append((start, end))

    # Sort intervals based on the start value
    copied.sort(key=lambda x: x[0])

    merged = []
    for interval in copied:
        if not merged:
            merged.append(interval)
        else:
            last_start, last_end = merged[-1]
            curr_start, curr_end = interval
            # Merge only if current interval overlaps or is adjacent
            if curr_start <= last_end:
                # Merge the intervals
                new_start = last_start
                new_end = max(last_end, curr_end)
                merged[-1] = (new_start, new_end)
            else:
                merged.append(interval)

    return merged
