class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__(f"Cycle detected: {cycle}")


def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    # 检查是否有未知节点
    node_set = set(nodes)
    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError("Edge contains unknown node")

    # 去重边
    unique_edges = set(edges)

    # 构建邻接表和入度表
    from collections import defaultdict
    graph = defaultdict(list)
    in_degree = {node: 0 for node in nodes}

    for a, b in unique_edges:
        graph[a].append(b)
        in_degree[b] += 1

    # 检测自环
    for a, b in unique_edges:
        if a == b:
            raise CycleError([a, a])

    # 拓扑排序，使用字典序最小的节点
    import heapq
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # 如果结果长度不等于节点数，说明有环
    if len(result) != len(nodes):
        # 找到一个环
        cycle = find_cycle(nodes, graph)
        raise CycleError(cycle)

    return result


def find_cycle(nodes, graph):
    """
    使用 DFS 找到一个环，并返回环路（首尾节点相同）
    """
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in nodes}
    parent = {}

    def dfs(node):
        color[node] = GRAY
        for neighbor in graph[node]:
            if color[neighbor] == GRAY:
                # 找到环
                cycle = [neighbor]
                current = node
                while current != neighbor:
                    cycle.append(current)
                    current = parent[current]
                cycle.append(neighbor)
                cycle.reverse()
                return cycle
            elif color[neighbor] == WHITE:
                parent[neighbor] = node
                result = dfs(neighbor)
                if result:
                    return result
        color[node] = BLACK
        return None

    for node in nodes:
        if color[node] == WHITE:
            parent[node] = None
            cycle = dfs(node)
            if cycle:
                return cycle
    return []
