import copy

def apply_patch_ops(document: dict, operations) -> dict:
    """
    对嵌套字典执行事务式更新。

    :param document: 原始文档（将被深拷贝，不会原地修改）
    :param operations: 操作列表，每项为 (op, path, value) 三元组
                       op 支持 'set', 'delete', 'increment'
                       path 为点分路径字符串
    :return: 更新后的新文档
    :raises Exception: 若任一步操作失败，则回滚并抛出异常
    """
    # 深拷贝输入文档，确保不修改调用者的原始数据
    new_doc = copy.deepcopy(document)

    # 保存操作前的状态用于回滚
    backup = copy.deepcopy(new_doc)

    def get_parent_and_key(path_parts):
        """获取路径的父节点和最后一个键"""
        parent = new_doc
        for key in path_parts[:-1]:
            if not isinstance(parent, dict) or key not in parent:
                return None, None
            parent = parent[key]
        return parent, path_parts[-1]

    try:
        for op, path, value in operations:
            path_parts = path.split('.')
            parent, last_key = get_parent_and_key(path_parts)

            if op == 'set':
                if parent is None:
                    # 自动创建中间路径
                    current = new_doc
                    for key in path_parts[:-1]:
                        if key not in current or not isinstance(current[key], dict):
                            current[key] = {}
                        current = current[key]
                    current[path_parts[-1]] = value
                else:
                    parent[last_key] = value

            elif op == 'delete':
                if parent is not None and last_key in parent:
                    del parent[last_key]
                # 如果路径不存在，不报错

            elif op == 'increment':
                if parent is None or last_key not in parent:
                    raise KeyError(f"Path '{path}' does not exist for increment operation")
                current_value = parent[last_key]
                if not isinstance(current_value, (int, float)) or isinstance(current_value, bool):
                    raise TypeError(f"Value at path '{path}' is not a number, cannot increment")
                if not isinstance(value, (int, float)) or isinstance(value, bool):
                    raise TypeError("Increment value must be a number")
                parent[last_key] = current_value + value

            else:
                raise ValueError(f"Unsupported operation: {op}")

    except Exception as e:
        # 回滚到备份状态
        new_doc.clear()
        new_doc.update(copy.deepcopy(backup))
        raise e

    return new_doc
