import threading
from collections import defaultdict


class VersionedStore:
    def __init__(self):
        self._lock = threading.RLock()
        self._data = {}  # key -> (version, value)
        self._versions = defaultdict(int)  # key -> current version

    def read(self, key):
        with self._lock:
            if key not in self._data:
                return None
            version, value = self._data[key]
            return copy.deepcopy(value)

    def compare_and_set(self, key, expected_version, value):
        with self._lock:
            current_version = self._versions[key]
            if current_version != expected_version:
                return False
            new_version = current_version + 1
            self._data[key] = (new_version, value)
            self._versions[key] = new_version
            return True

    def delete(self, key, expected_version):
        with self._lock:
            current_version = self._versions[key]
            if current_version != expected_version:
                return False
            if key in self._data:
                del self._data[key]
            new_version = current_version + 1
            self._versions[key] = new_version
            return True

    def snapshot(self):
        with self._lock:
            snapshot_data = {}
            for key, (version, value) in self._data.items():
                snapshot_data[key] = (version, copy.deepcopy(value))
            return snapshot_data
