class ReplicatedLog:
    def __init__(self):
        self.log = []  # list of (term, command)
        self.commit_index = -1
        self.last_applied = -1
        self.current_term_value = 0

    def append(self, command):
        self.log.append((self.current_term_value, command))
        return len(self.log) - 1

    def receive_append(self, term, prev_index, prev_term, entries, leader_commit):
        if term < self.current_term_value:
            return False, 0
        if term > self.current_term_value:
            self.current_term_value = term

        # Check prev_log
        if prev_index >= 0:
            if prev_index >= len(self.log):
                return False, prev_index
            if self.log[prev_index][0] != prev_term:
                return False, prev_index

        # Find conflict point
        start = prev_index + 1
        for i in range(start, len(self.log)):
            if i - start < len(entries):
                if self.log[i][0] != entries[i - start][0]:
                    # Conflict found
                    self.log = self.log[:i] + entries[i - start:]
                    break
            else:
                self.log = self.log[:i] + entries
                break
        else:
            # No conflict, append remaining
            self.log = self.log[:start] + entries

        # Update commit index
        if leader_commit > self.commit_index:
            self.commit_index = min(leader_commit, len(self.log) - 1)

        return True, -1

    def commit_to(self, index):
        if index <= self.commit_index:
            return
        if index >= len(self.log):
            index = len(self.log) - 1
        self.commit_index = index

    def apply_committed(self):
        if self.last_applied >= self.commit_index:
            return []
        self.last_applied = min(self.last_applied + 1, self.commit_index)
        return [self.log[self.last_applied][1]]

    def current_index(self):
        return len(self.log) - 1

    def current_term(self):
        return self.current_term_value
